#[tokio::test(flavor = "current_thread")]
async fn fetch_data_and_blob_urls_resolve_locally() {
    let mut rt = setup_runtime("<html><body></body></html>");
    // obscura #907 family: fetch()/XHR on data: and blob: URLs. These
    // never touch the HTTP client (it cannot fetch either scheme) — the
    // data: processor decodes inline bytes, and createObjectURL feeds a
    // registry fetch reads back. The old createObjectURL was a fake stub
    // whose URL nothing could resolve.
    let script = r#"async () => {
            const out = [];
            const t = await fetch('data:text/plain,hello%20w%C3%B6rld');
            out.push(t.status, t.headers.get('content-type'), await t.text());
            const j = await fetch('data:application/json;base64,eyJhIjoxfQ==');
            out.push(j.headers.get('content-type'), await j.text());
            const b = new Blob([new Uint8Array([104, 105])], { type: 'text/x-custom' });
            const u = URL.createObjectURL(b);
            out.push(typeof u === 'string' && u.startsWith('blob:'));
            const r = await fetch(u);
            out.push(r.status, r.headers.get('content-type'), await r.text());
            URL.revokeObjectURL(u);
            let revoked = false;
            try { await fetch(u); } catch (e) { revoked = true; }
            out.push(revoked);
            // XHR rides the same fetch branch.
            const xhrText = await new Promise((res, rej) => {
                const x = new XMLHttpRequest();
                x.open('GET', 'data:text/plain,xhr%21');
                x.onload = () => res(x.responseText + ':' + x.status);
                x.onerror = () => rej(new Error('xhr data: fetch failed'));
                x.send();
            });
            out.push(xhrText);
            return out;
        }"#;
    let result = rt
        .call_function_on_remote(script, None, &[], true, true)
        .await
        .unwrap();
    assert_eq!(
        result.value.unwrap(),
        serde_json::json!([
            200,
            "text/plain",
            "hello wörld",
            "application/json",
            "{\"a\":1}",
            true,
            200,
            "text/x-custom",
            "hi",
            true,
            "xhr!:200"
        ])
    );
}

#[cfg(feature = "screenshot")]
#[tokio::test(flavor = "current_thread")]
async fn test_float_wrap_lines_start_after_the_float_then_return_to_the_edge() {
    // Chrome truth (headless Chrome, 2026-10-22): container 200px, a
    // 50x50 left float, then a p of short words at line-height 20px. The
    // p BOX starts at x=0 and overlaps the float; its line boxes start at
    // 50, 50, 50 (their tops are above the float's bottom), then 0.
    diting_layout::float_flow::force(Some(true));
    let mut rt = setup_runtime(
            "<html><head><style>body{margin:0;font:16px/20px serif} p{margin:0}</style></head><body>
              <div id=c style=\"width:200px\"><div style=\"float:left;width:50px;height:50px\"></div><p id=p>word word word word word word word word word word word word word word word word word word word word</p></div>
             </body></html>",
        );
    let v = rt
            .evaluate(
                "(() => { const p = document.getElementById('p'); const b = p.getBoundingClientRect();
                  const r = document.createRange(); r.selectNodeContents(p);
                  const lefts = [...r.getClientRects()].map(x => Math.round(x.left));
                  return JSON.stringify([Math.round(b.left), Math.round(b.width), lefts.slice(0, 5), Math.round(b.height) % 20]); })()",
            )
            .unwrap();
    diting_layout::float_flow::force(None);
    assert_eq!(v, "[0,200,[50,50,50,0,0],0]");
}

