#[tokio::test(flavor = "current_thread")]
async fn test_table_caption_sizes_the_table_by_its_longest_word_only() {
    // Chrome truth (headless Chrome, 2026-10-22): a floated display:table
    // figure with a long display:table-caption is as wide as its content
    // (100), the caption fills that width; a caption holding one long
    // unbreakable word widens the table to that word (292). Wikipedia's
    // thumbnails are exactly this shape (#303).
    let mut rt = setup_runtime(
            "<html><head><style>body{margin:0;font:16px/20px serif}</style></head><body>
              <figure id=f style=\"display:table;float:right;margin:0\"><div style=\"width:100px;height:50px\"></div><figcaption id=c style=\"display:table-caption;caption-side:bottom\">This is a fairly long caption sentence that would be much wider than the image if it counted toward the width of the table</figcaption></figure>
              <figure id=g style=\"display:table;float:right;clear:right;margin:0\"><div style=\"width:30px;height:20px\"></div><figcaption id=h style=\"display:table-caption\">Unbreakableextraordinarilylongcaptionword</figcaption></figure>
             </body></html>",
        );
    let v = rt
            .evaluate(
                "(() => { const w = id => Math.round(document.getElementById(id).getBoundingClientRect().width);
                  return JSON.stringify([w('f'), w('c'), w('g') > 100 && w('h') === w('g'), getComputedStyle(document.getElementById('c')).display]); })()",
            )
            .unwrap();
    assert_eq!(v, "[100,100,true,\"table-caption\"]");
}

#[tokio::test(flavor = "current_thread")]
async fn test_hidden_children_do_not_cut_the_text_run() {
    // Chrome truth (headless Chrome, 2026-10-22): `<link>`, `<meta>` and a
    // display:none <br> between words build no box, so the paragraph wraps
    // exactly like the same text without them (2 lines at 500px); the
    // engine broke the line at each one (5 lines) - Wikipedia's category
    // <link>s sit inside paragraphs (#304).
    let mut rt = setup_runtime(
            "<html><head><style>body{margin:0;font:16px/20px serif} p{width:500px;margin:0} .h{display:none}</style></head><body>
              <p id=a>alpha beta gamma <link rel=x href=./a> delta epsilon <meta name=y> zeta eta theta <br class=h> iota kappa lambda mu nu xi omicron pi rho sigma tau upsilon phi chi psi omega</p>
              <p id=b>alpha beta gamma  delta epsilon  zeta eta theta  iota kappa lambda mu nu xi omicron pi rho sigma tau upsilon phi chi psi omega</p>
             </body></html>",
        );
    let v = rt
            .evaluate("(() => { const h = id => Math.round(document.getElementById(id).getBoundingClientRect().height); return h('a') + ':' + h('b'); })()")
            .unwrap();
    let (a, b) = v.as_str().unwrap().split_once(':').unwrap();
    assert_eq!(a, b, "hidden children must not add lines (a={a}, b={b})");
}

#[tokio::test(flavor = "current_thread")]
async fn test_nested_percent_width_tables_in_rowspan_cells_keep_their_width() {
    // Wikipedia's clade trees: each level is a `td rowspan=2` holding a
    // `width:100%` table. The rowspan placeholder added nothing to the
    // row's intrinsic width, so every level squeezed the next (the
    // innermost table collapsed to 0px, #305). Rowspan on or off, the
    // widths must agree (Chrome: both 232/169/73 with its fonts).
    let table = |rs: &str, ids: &str| {
        format!(
                "<table id=o{ids}><tr><td style=\"white-space:nowrap\">Felidae</td><td {rs}><div><table id=a{ids} style=\"width:100%\"><tr><td style=\"white-space:nowrap\">Pantherinae</td><td {rs}><div><table id=b{ids} style=\"width:100%\"><tr><td style=\"white-space:nowrap\">Jungle cat</td></tr></table></div></td></tr><tr><td></td></tr></table></div></td></tr><tr><td></td></tr></table>"
            )
    };
    let html = format!(
            "<html><head><style>body{{margin:0;font:16px/20px serif}} table{{border-spacing:0;margin:0}} td{{padding:0 4px;vertical-align:top}}</style></head><body>{}{}</body></html>",
            table("rowspan=2", "1"),
            table("", "2")
        );
    let mut rt = setup_runtime(&html);
    let v = rt
            .evaluate("(() => { const w = id => Math.round(document.getElementById(id).getBoundingClientRect().width); return [w('a1') - w('a2'), w('b1') - w('b2'), w('b1') > 60].join(','); })()")
            .unwrap();
    assert_eq!(v, "0,0,true");
}

#[tokio::test(flavor = "current_thread")]
async fn test_auto_inset_absolute_boxes_sit_at_their_static_position() {
    // Chrome truth (headless Chrome, 2026-10-22): an absolute box with
    // top/left auto sits where it would have been in flow - here the top of
    // its static parent - however far down the page that is; the page is
    // 3500 tall (the rotated box's overflow aside). The harvest added the parent chain on top of the
    // containing-block-relative location, so it landed at 2x (6000) and
    // doubled the page (#306: Wikipedia's navbox labels).
    let mut rt = setup_runtime(
            "<html><body style=\"margin:0\"><div style=\"height:3000px\"></div>
              <div id=c1 style=\"height:100px\"><div id=d1 style=\"position:absolute\">abs</div>x</div>
              <div id=c2 style=\"height:100px\"><div id=d2 style=\"position:absolute;transform:rotate(270deg)\">rot</div>x</div>
              <div id=c3 style=\"height:100px;position:relative\"><div id=d3 style=\"position:absolute\">rel</div>x</div>
              <div style=\"height:200px\"></div></body></html>",
        );
    let v = rt
            .evaluate(
                "(() => { const t = id => Math.round(document.getElementById(id).getBoundingClientRect().top + scrollY);
                  return [t('d1') - t('c1'), Math.abs(t('d2') - t('c2')) < 80, t('d3') - t('c3'), document.documentElement.scrollHeight < 3700].join(','); })()",
            )
            .unwrap();
    assert_eq!(v, "0,true,0,true");
}

#[test]
fn test_insert_before_and_replace_child_report_to_mutation_observers() {
    // insertBefore/replaceChild ran the tree mutation but never notified
    // MutationObserver — before()/after()/replaceWith() route through
    // insertBefore, so they were silent too.
    let mut rt = setup_runtime(r#"<main id="host"><p id="a"></p><p id="b"></p></main>"#);
    let result = rt
        .evaluate(
            r#"
            const host = document.getElementById('host');
            const observer = new MutationObserver(() => {});
            observer.observe(host, { childList: true });
            const x = document.createElement('x-i');
            host.insertBefore(x, document.getElementById('b'));
            const y = document.createElement('x-r');
            host.replaceChild(y, document.getElementById('a'));
            // Observer delivery is a microtask; takeRecords() drains
            // synchronously.
            return observer.takeRecords().map(r => [r.addedNodes.length, r.removedNodes.length]);
        "#,
        )
        .unwrap();
    assert_eq!(result, serde_json::json!([[1, 0], [1, 1]]));
}

#[test]
fn test_url_reflection_src_and_href_resolve_absolute() {
    // Next.js/Turbopack webpack runtime does `new URL(x, document.currentScript.src)`
    // to derive its chunk base. If src/href return the raw relative attribute,
    // the base has no scheme and URL construction throws "TypeError: Invalid
    // scheme", so React never hydrates. URL-reflection attributes must return
    // the resolved absolute URL like real browsers.
    let mut rt = setup_runtime(
        r#"<html><head><script src="/app.js"></script>
            <link rel="stylesheet" href="/style.css"></head><body>
            <img id="logo" src="/logos/x.png"><a id="link" href="/docs">docs</a></body></html>"#,
    );
    let res = rt.evaluate(r#"
            const out = {};
            out.scriptSrc = document.querySelector('script').src;
            out.linkHref = document.querySelector('link').href;
            out.imgSrc = document.getElementById('logo').src;
            out.anchorHref = document.getElementById('link').href;
            out.dataSrc = (function(){ const i = document.createElement('img'); i.setAttribute('src', 'data:image/png;base64,AAA'); return i.src; })();
            out.absSrc = (function(){ const i = document.createElement('img'); i.setAttribute('src', 'https://cdn.example.com/x.png'); return i.src; })();
            out.emptySrc = (function(){ const i = document.createElement('img'); i.setAttribute('src', ''); return i.src; })();
            out.missingSrc = document.createElement('img').src;
            return JSON.stringify(out);
        "#).unwrap();
    let v = serde_json::from_str::<serde_json::Value>(res.as_str().unwrap()).unwrap();
    assert_eq!(v["scriptSrc"], "http://example.com/app.js");
    assert_eq!(v["linkHref"], "http://example.com/style.css");
    assert_eq!(v["imgSrc"], "http://example.com/logos/x.png");
    assert_eq!(v["anchorHref"], "http://example.com/docs");
    assert_eq!(
        v["dataSrc"], "data:image/png;base64,AAA",
        "data: URLs stay absolute"
    );
    assert_eq!(
        v["absSrc"], "https://cdn.example.com/x.png",
        "absolute stays absolute"
    );
    assert_eq!(
        v["emptySrc"], "http://example.com/test",
        "empty src resolves to the document URL"
    );
    assert_eq!(
        v["missingSrc"], "",
        "missing src attribute reflects as empty"
    );
}

#[test]
fn test_stealth_fingerprint_apis_pluginarray_and_webgl() {
    // authk.smithery.ai (WorkOS+Cloudflare) crashed after hydration:
    // `ReferenceError: PluginArray is not defined` (bot-detector references
    // the constructor) and `e.uniform2f is not a function` (missing WebGL
    // methods). These must exist and behave like real browsers.
    let mut rt = setup_runtime("<html><body><canvas id='c'></canvas></body></html>");
    let res = rt.evaluate(r#"
            const out = {};
            out.pluginArrayDefined = typeof PluginArray !== 'undefined';
            out.pluginsIsInstance = navigator.plugins instanceof PluginArray;
            out.pluginsLength = navigator.plugins.length;
            out.pluginsIdentity = navigator.plugins === navigator.plugins;
            out.mimeIdentity = navigator.mimeTypes === navigator.mimeTypes;
            out.pluginLength = navigator.plugins[0] && navigator.plugins[0].length;
            out.mimeIsInstance = navigator.mimeTypes instanceof MimeTypeArray;
            // (#125) Chrome's PDF persona is a linked graph, verified against
            // a real headless Chrome 145 dump: each plugin carries both mime
            // types as members (length 2), item()/namedItem() resolve them,
            // every mime's enabledPlugin IS navigator.plugins[0] by identity,
            // and the member MimeType objects are the SAME instances
            // navigator.mimeTypes exposes.
            out.p00 = navigator.plugins[0][0] && navigator.plugins[0][0].type;
            out.p01 = navigator.plugins[0][1] && navigator.plugins[0][1].type;
            out.p4len = navigator.plugins[4] && navigator.plugins[4].length;
            out.pItem = navigator.plugins[0].item(0) && navigator.plugins[0].item(0).type;
            out.pNamed = navigator.plugins[0].namedItem("text/pdf") && navigator.plugins[0].namedItem("text/pdf").type;
            out.mt0Owner = navigator.mimeTypes[0].enabledPlugin && navigator.mimeTypes[0].enabledPlugin.name;
            out.mt1Owner = navigator.mimeTypes[1] && navigator.mimeTypes[1].enabledPlugin && navigator.mimeTypes[1].enabledPlugin.name;
            out.mt0OwnerIsP0 = navigator.mimeTypes[0].enabledPlugin === navigator.plugins[0];
            out.p00IsMt0 = navigator.plugins[0][0] === navigator.mimeTypes[0];
            out.p0keys = Object.keys(navigator.plugins[0]);
            const c = document.getElementById('c');
            const gl = c.getContext('webgl');
            out.gl = !!gl;
            out.glIdentity = c.getContext('webgl') === gl;
            out.glInstanceof = gl instanceof WebGLRenderingContext;
            out.gl2Instanceof = document.createElement('canvas').getContext('webgl2') instanceof WebGL2RenderingContext;
            out.glNotThenable = gl.then === undefined;
            out.glSymbolUndefined = gl[Symbol.iterator] === undefined;
            out.uniform2f = typeof gl.uniform2f === 'function';
            out.getContextAttributes = typeof gl.getContextAttributes === 'function' && !!gl.getContextAttributes();
            out.getError = gl.getError() === 0;
            out.unknownMethod = (function(){ try { return typeof gl.someUnknownMethod === 'undefined' && (function(){ try { gl.someUnknownMethod(1,2); return false; } catch(e) { return e instanceof TypeError; } })(); } catch(e) { return 'threw:' + e.message; } })();
            return JSON.stringify(out);
        "#).unwrap();
    let v = serde_json::from_str::<serde_json::Value>(res.as_str().unwrap()).unwrap();
    assert_eq!(
        v["pluginArrayDefined"], true,
        "PluginArray global must exist"
    );
    assert_eq!(
        v["pluginsIsInstance"], true,
        "navigator.plugins must be a PluginArray"
    );
    assert_eq!(v["pluginsLength"].as_i64().unwrap(), 5);
    assert_eq!(
        v["pluginsIdentity"], true,
        "plugins must be a cached singleton (identity is fingerprintable)"
    );
    assert_eq!(
        v["mimeIdentity"], true,
        "mimeTypes must be a cached singleton"
    );
    assert_eq!(
        v["pluginLength"].as_i64().unwrap(),
        2,
        "Chrome PDF plugins carry both mime types"
    );
    assert_eq!(v["mimeIsInstance"], true);
    assert_eq!(
        v["p00"], "application/pdf",
        "plugins[0][0] must expose the member MimeType"
    );
    assert_eq!(
        v["p01"], "text/pdf",
        "plugins[0][1] must expose the second member MimeType"
    );
    assert_eq!(
        v["p4len"].as_i64().unwrap(),
        2,
        "every PDF plugin carries both members"
    );
    assert_eq!(
        v["pItem"], "application/pdf",
        "Plugin.item(0) must resolve the member"
    );
    assert_eq!(
        v["pNamed"], "text/pdf",
        "Plugin.namedItem must resolve by mime type"
    );
    assert_eq!(
        v["mt0Owner"], "PDF Viewer",
        "mimeTypes[0].enabledPlugin must name the owning plugin"
    );
    assert_eq!(
        v["mt1Owner"], "PDF Viewer",
        "text/pdf is also owned by the first plugin"
    );
    assert_eq!(
        v["mt0OwnerIsP0"], true,
        "enabledPlugin must be navigator.plugins[0] by identity"
    );
    assert_eq!(
        v["p00IsMt0"], true,
        "plugin members and navigator.mimeTypes share MimeType instances"
    );
    assert_eq!(
        v["p0keys"],
        serde_json::json!(["0", "1"]),
        "Object.keys(plugin) shows member indices only (Chrome puts name/length on the prototype)"
    );
    assert_eq!(v["gl"], true);
    assert_eq!(
        v["glIdentity"], true,
        "getContext must return the same context on repeat calls"
    );
    assert_eq!(
        v["glInstanceof"], true,
        "gl must be instanceof WebGLRenderingContext"
    );
    assert_eq!(
        v["gl2Instanceof"], true,
        "webgl2 context must be instanceof WebGL2RenderingContext"
    );
    assert_eq!(
        v["glNotThenable"], true,
        "gl.then must stay undefined or the context becomes thenable"
    );
    assert_eq!(
        v["glSymbolUndefined"], true,
        "symbol props must not hit the numNoop fallback"
    );
    assert_eq!(v["uniform2f"], true, "uniform2f must exist");
    assert_eq!(v["getContextAttributes"], true);
    assert_eq!(v["getError"], true);
    assert_eq!(v["unknownMethod"], true, "(刀69) a name Chrome lacks is undefined and calling it is a TypeError — the number-ish Proxy fallback is gone");
}

#[test]
fn test_stealth_webgl_chrome_truth_interface_shape() {
    // (P8 #300015) The WebGL interface must match Chrome 154 byte-for-byte
    // at the reflection level: the INSTANCE carries zero own properties,
    // the PROTOTYPE carries exactly 442/791 own names (constants +
    // methods + 6 accessors), constants are enumerable/non-writable/
    // non-configurable, and extension objects keep their constants on the
    // carrier prototype. The old shape leaked ~80 own props on the
    // instance and a 29-entry constant table — a counting detector's
    // one-liner. Truth captured from real Chrome 154.0.8037.98 (macOS);
    // 154 lacks makeXRCompatible (155 added it), hence -1 vs the 155 pin.
    let mut rt = setup_runtime(
        "<html><body><canvas id='c' width='320' height='200'></canvas></body></html>",
    );
    let res = rt.evaluate(r#"
            const out = {};
            const c = document.getElementById('c');
            const gl = c.getContext('webgl');
            const gl2 = document.createElement('canvas').getContext('webgl2');
            const P1 = WebGLRenderingContext.prototype;
            const P2 = WebGL2RenderingContext.prototype;
            out.instKeys1 = Object.keys(gl).length;
            out.instKeys2 = Object.keys(gl2).length;
            out.instNames1 = Object.getOwnPropertyNames(gl).length;
            out.protoNames1 = Object.getOwnPropertyNames(P1).length;
            out.protoNames2 = Object.getOwnPropertyNames(P2).length;
            out.protoKeys1 = Object.keys(P1).length;
            out.protoKeys2 = Object.keys(P2).length;
            const d = Object.getOwnPropertyDescriptor(P1, 'VERTEX_SHADER');
            out.constDesc = [d.value, d.writable, d.enumerable, d.configurable];
            const md = Object.getOwnPropertyDescriptor(P1, 'getParameter');
            out.methodDesc = [md.writable, md.enumerable, md.configurable, typeof md.get];
            out.ctorEnum = Object.getOwnPropertyDescriptor(P1, 'constructor').enumerable;
            out.acc = Object.getOwnPropertyDescriptor(P1, 'canvas');
            out.accIsGetter = typeof out.acc.get === 'function' && out.acc.set === undefined && !('value' in out.acc);
            out.canvasIsC = gl.canvas === c;
            out.dbw = gl.drawingBufferWidth;
            out.dbh = gl.drawingBufferHeight;
            out.dbcs = gl.drawingBufferColorSpace;
            out.ucs = gl.unpackColorSpace;
            out.dbf = gl.drawingBufferFormat;
            out.dbf2 = gl2.drawingBufferFormat;
            const ext = gl.getExtension('WEBGL_debug_renderer_info');
            out.extKeys = Object.keys(ext).length;
            out.extNames = Object.getOwnPropertyNames(ext).length;
            out.extConstIn = 'UNMASKED_VENDOR_WEBGL' in ext;
            out.extConstVal = ext.UNMASKED_VENDOR_WEBGL;
            out.extCtorName = ext.constructor && ext.constructor.name;
            out.extProtoProtoObject = Object.getPrototypeOf(Object.getPrototypeOf(ext)) === Object.prototype;
            const lose = gl.getExtension('WEBGL_lose_context');
            out.loseMethods = typeof lose.loseContext === 'function' && typeof lose.restoreContext === 'function';
            out.loseOwn = Object.keys(lose).length;
            out.gl2Methods = typeof gl2.createVertexArray === 'function' && typeof gl2.transformFeedbackVaryings === 'function';
            out.gl2Const = gl2.TEXTURE_BINDING_3D === 32874 && gl2.MAX_ELEMENT_INDEX === 36203;
            out.memPow2 = [8, 16, 32].includes(navigator.deviceMemory);
            out.memGt8Possible = navigator.deviceMemory >= 8;
            return JSON.stringify(out);
        "#).unwrap();
    let v = serde_json::from_str::<serde_json::Value>(res.as_str().unwrap()).unwrap();
    assert_eq!(
        v["instKeys1"], 0,
        "GL1 instance must carry ZERO own enumerable props (Chrome: [])"
    );
    assert_eq!(
        v["instKeys2"], 0,
        "GL2 instance must carry ZERO own enumerable props"
    );
    assert_eq!(
        v["instNames1"], 0,
        "GL1 instance must carry ZERO own props of any kind (only hidden _canvas)"
    );
    assert_eq!(
            v["protoNames1"].as_i64().unwrap(),
            443,
            "GL1 prototype own-name count must be exactly Chrome 145's 443 (298 consts + 138 methods + 6 accessors + makeXRCompatible)"
        );
    assert_eq!(
            v["protoNames2"].as_i64().unwrap(),
            792,
            "GL2 prototype own-name count must be exactly Chrome 145's 792 (559 + 226 + 6 + makeXRCompatible)"
        );
    assert_eq!(
        v["protoKeys1"].as_i64().unwrap(),
        442,
        "GL1 enumerable proto keys = 442 (constructor is non-enumerable)"
    );
    assert_eq!(
        v["protoKeys2"].as_i64().unwrap(),
        791,
        "GL2 enumerable proto keys = 791"
    );
    assert_eq!(
        v["constDesc"],
        serde_json::json!([35633, false, true, false]),
        "constants: value-carrying, enumerable, NON-writable, NON-configurable"
    );
    assert_eq!(
        v["methodDesc"],
        serde_json::json!([true, true, true, "undefined"]),
        "methods: writable+enumerable+configurable, not accessors"
    );
    assert_eq!(
        v["ctorEnum"], false,
        "constructor stays non-enumerable (the class default)"
    );
    assert_eq!(
        v["accIsGetter"], true,
        "canvas must be a getter-only accessor (no value, no set)"
    );
    assert_eq!(v["acc"]["enumerable"], true);
    assert_eq!(v["acc"]["configurable"], true);
    assert_eq!(
        v["canvasIsC"], true,
        "gl.canvas must be the creating canvas by identity"
    );
    assert_eq!(
        v["dbw"].as_i64().unwrap(),
        320,
        "drawingBufferWidth tracks the canvas width"
    );
    assert_eq!(
        v["dbh"].as_i64().unwrap(),
        200,
        "drawingBufferHeight tracks the canvas height"
    );
    assert_eq!(v["dbcs"], "srgb");
    assert_eq!(v["ucs"], "srgb");
    assert_eq!(
        v["dbf"].as_i64().unwrap(),
        32856,
        "drawingBufferFormat is the GLenum GL_RGBA8 (0x8058)"
    );
    assert_eq!(v["dbf2"].as_i64().unwrap(), 32856);
    assert_eq!(
        v["extKeys"], 0,
        "extension objects carry ZERO own enumerable props"
    );
    assert_eq!(
        v["extNames"], 0,
        "extension objects carry ZERO own props, period"
    );
    assert_eq!(
        v["extConstIn"], true,
        "the ext constant resolves through the carrier prototype"
    );
    assert_eq!(v["extConstVal"].as_i64().unwrap(), 0x9245);
    assert_eq!(
        v["extCtorName"], "Object",
        "Chrome ext objects report constructor name \"Object\""
    );
    assert_eq!(
        v["extProtoProtoObject"], true,
        "carrier chain ends at Object.prototype"
    );
    assert_eq!(
        v["loseMethods"], true,
        "WEBGL_lose_context carries loseContext/restoreContext"
    );
    assert_eq!(v["loseOwn"], 0);
    assert_eq!(
        v["gl2Methods"], true,
        "GL2-only methods must exist (createVertexArray, transformFeedbackVaryings)"
    );
    assert_eq!(
        v["gl2Const"], true,
        "GL2-only constants must resolve (TEXTURE_BINDING_3D)"
    );
    assert_eq!(
        v["memPow2"], true,
        "deviceMemory must be a power-of-two GiB value from the persona table"
    );
    assert_eq!(
        v["memGt8Possible"], true,
        "Chrome 155 dropped the 8 GiB cap — persona mem can exceed 8"
    );
}

/// Resource Timing §4.4: a full buffer parks new entries and fires
/// `resourcetimingbufferfull`; a handler that clears (or grows) the buffer
/// gets the parked entries back, no handler drops them. The old shape
/// dropped silently — on asset-heavy pages (fxg create page, ~250 boot
/// loads) every later fetch/XHR vanished from the buffer.
#[tokio::test(flavor = "current_thread")]
async fn resource_timing_buffer_full_event_refills_after_clear() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let res = rt
        .call_function_on_remote(
            r#"async () => {
                const out = {};
                const tick = () => new Promise((r) => setTimeout(r, 0));
                const rec = (n) => performance._recordResource({ name: n, startTime: 0, duration: 1, initiatorType: 'fetch' });
                performance.setResourceTimingBufferSize(2);
                let fired = 0;
                rec('a'); rec('b'); rec('c');
                await tick(); await tick();
                out.noHandler = performance.getEntriesByType('resource').map((e) => e.name).join(',');
                performance.onresourcetimingbufferfull = () => { fired++; performance.clearResourceTimings(); };
                rec('d'); rec('e');
                await tick(); await tick();
                out.fired = fired;
                out.afterClear = performance.getEntriesByType('resource').map((e) => e.name).join(',');
                return JSON.stringify(out);
            }"#,
            None,
            &[],
            true,
            true,
        )
        .await
        .unwrap();
    let v =
        serde_json::from_str::<serde_json::Value>(res.value.unwrap().as_str().unwrap()).unwrap();
    assert_eq!(
        v["noHandler"], "a,b",
        "no handler: the parked entry is dropped"
    );
    assert_eq!(v["fired"], 1, "one event per full episode");
    assert_eq!(
        v["afterClear"], "d,e",
        "the handler's clear lets the parked entries in"
    );
}

/// #126: the resource-timing buffer carries REAL entries from both
/// faces — the navigation pipeline's fetch timings (Rust-recorded,
/// epoch-stamped, converted into the resource clock) and the fetch/XHR
/// shims' own samples (recorded in-page). Nothing fabricated: a request
/// without a measurement stays absent, and clearResourceTimings
/// empties BOTH faces.
#[tokio::test(flavor = "current_thread")]
async fn resource_timing_buffer_carries_real_entries() {
    let mut rt = setup_runtime("<html><body></body></html>");
    rt.push_resource_timings(vec![crate::ops::ResourceTimingRecord {
        name: "http://example.com/sheet.css".to_string(),
        initiator: "link",
        // Deliberately BEFORE timeOrigin: pre-init fetches clamp to 0.
        start_epoch_ms: 1.0,
        duration_ms: 42.5,
        status: 200,
        body_size: 1024,
        render_blocking: true,
    }]);
    // The assertions await real fetches, so they ride the
    // callFunctionOn await-promise channel (evaluate is sync-script
    // semantics and would hand back the function object itself).
    let res = rt
            .call_function_on_remote(
                r#"async () => {
                const out = {};
                // Rust face: entry shape, clock clamp, blocking posture.
                let rs = performance.getEntriesByType('resource');
                out.rustCount = rs.length;
                const e = rs[0];
                out.name = e && e.name;
                out.initiator = e && e.initiatorType;
                out.entryType = e && e.entryType;
                out.startTime = e && e.startTime;
                out.duration = e && e.duration;
                out.encoded = e && e.encodedBodySize;
                out.decoded = e && e.decodedBodySize;
                out.status = e && e.responseStatus;
                out.blocking = e && e.renderBlockingStatus;
                out.instance = e instanceof PerformanceResourceTiming;
                out.illegal = (function(){ try { new PerformanceResourceTiming(); return false; } catch (err) { return /Illegal constructor/.test(err.message); } })();
                out.getEntriesHasIt = performance.getEntries().some((x) => x.entryType === 'resource' && x.name === 'http://example.com/sheet.css');
                out.toJSONKeys = e ? Object.keys(e.toJSON()).sort().join(',') : '';
                // JS face: a real fetch() records its own sample.
                await fetch('data:text/plain,hello');
                rs = performance.getEntriesByType('resource');
                out.afterFetch = rs.length;
                const f = rs.find((x) => x.initiatorType === 'fetch');
                out.fetchName = f && f.name.slice(0, 15);
                out.fetchDur = f && (f.duration >= 0 && f.duration < 1000);
                out.fetchBody = f && f.encodedBodySize;
                out.fetchStatus = f && f.responseStatus;
                // Async XHR delegates to fetch but must label itself.
                await new Promise((resolve) => {
                    const x = new XMLHttpRequest();
                    x.open('GET', 'data:text/plain,wxhr');
                    x.onload = () => resolve();
                    x.onerror = () => resolve();
                    x.send();
                });
                const x = performance.getEntriesByType('resource').find((e2) => e2.initiatorType === 'xmlhttprequest');
                out.xhrEntry = !!x;
                // Cap: the in-page buffer drops beyond the limit.
                performance.setResourceTimingBufferSize(3);
                for (let i = 0; i < 5; i++) await fetch('data:text/plain,cap' + i);
                const all = performance.getEntriesByType('resource');
                out.capped = all.filter((e2) => e2.initiatorType === 'fetch').length;
                // Clear empties BOTH faces (the Rust record included).
                performance.clearResourceTimings();
                out.cleared = performance.getEntriesByType('resource').length;
                return JSON.stringify(out);
            }"#,
                None,
                &[],
                true,
                true,
            )
            .await
            .unwrap();
    let v =
        serde_json::from_str::<serde_json::Value>(res.value.unwrap().as_str().unwrap()).unwrap();
    assert_eq!(
        v["rustCount"].as_i64().unwrap(),
        1,
        "Rust-recorded sheet must appear"
    );
    assert_eq!(v["name"], "http://example.com/sheet.css");
    assert_eq!(v["initiator"], "link");
    assert_eq!(v["entryType"], "resource");
    assert_eq!(
        v["startTime"].as_f64().unwrap(),
        0.0,
        "pre-timeOrigin starts clamp to 0"
    );
    assert_eq!(
        v["duration"].as_f64().unwrap(),
        42.5,
        "duration is the real measurement"
    );
    assert_eq!(v["encoded"].as_i64().unwrap(), 1024);
    assert_eq!(v["decoded"].as_i64().unwrap(), 1024);
    assert_eq!(v["status"].as_i64().unwrap(), 200);
    assert_eq!(v["blocking"], "blocking", "stylesheets block first render");
    assert_eq!(
        v["instance"], true,
        "entries must be PerformanceResourceTiming instances"
    );
    assert_eq!(v["illegal"], true, "page code still cannot construct one");
    assert_eq!(
        v["getEntriesHasIt"], true,
        "getEntries() must include resource entries"
    );
    assert!(
        v["toJSONKeys"].as_str().unwrap().contains("initiatorType"),
        "toJSON carries resource fields"
    );
    assert_eq!(
        v["afterFetch"].as_i64().unwrap(),
        2,
        "fetch() adds one real entry"
    );
    assert_eq!(v["fetchName"], "data:text/plain");
    assert_eq!(
        v["fetchDur"], true,
        "duration is a real local measurement (data: resolves synchronously, 0 is honest)"
    );
    assert_eq!(
        v["fetchBody"].as_i64().unwrap(),
        5,
        "encodedBodySize is the body length"
    );
    assert_eq!(v["fetchStatus"].as_i64().unwrap(), 200);
    assert_eq!(
        v["xhrEntry"], true,
        "async XHR labels its delegated entry xmlhttprequest"
    );
    assert_eq!(
        v["capped"].as_i64().unwrap(),
        2,
        "cap holds: hello fetch + XHR predate it, one slot left for the cap run"
    );
    assert_eq!(
        v["cleared"].as_i64().unwrap(),
        0,
        "clearResourceTimings empties both faces"
    );
}

#[test]
fn test_navigator() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let ua = rt.evaluate("navigator.userAgent").unwrap();
    assert!(
        ua.as_str().unwrap().contains("Chrome"),
        "UA should contain Chrome: {}",
        ua
    );
    let wd = rt.evaluate("navigator.webdriver").unwrap();
    // (#78) Chrome defines webdriver (NavigatorAutomationInformation) and
    // it reads false on a normal session — `undefined` was the outlier.
    assert_eq!(wd, serde_json::json!(false));
    let plugins = rt.evaluate("navigator.plugins.length").unwrap();
    assert!(plugins.as_f64().unwrap() > 0.0, "Should have plugins");
    let chrome = rt.evaluate("typeof window.chrome").unwrap();
    assert_eq!(chrome, serde_json::json!("object"));
}

#[test]
fn test_issue_81_service_worker_event_target() {
    // X's bootstrap does `navigator.serviceWorker?.addEventListener(...)`.
    // `?.` only guards null/undefined — a truthy container without the
    // EventTarget methods throws TypeError and the page renders its
    // failure branch ("Something went wrong") while the network face is
    // fine. The container must be a functioning EventTarget (issue #81).
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
        .evaluate(
            r#"
            var sw = navigator.serviceWorker;
            var booted = true;
            try { sw?.addEventListener('message', function () {}); } catch (e) { booted = false; }
            return [
                typeof sw,
                typeof sw.addEventListener,
                typeof sw.removeEventListener,
                typeof sw.dispatchEvent,
                typeof sw.register,
                typeof sw.getRegistration,
                typeof sw.getRegistrations,
                booted,
                sw.dispatchEvent(new Event('x')),
                sw.addEventListener.toString().indexOf('[native code]') !== -1,
            ];
        "#,
        )
        .unwrap();
    assert_eq!(
        result,
        serde_json::json!([
            "object", "function", "function", "function", "function", "function", "function",
            // dispatchEvent of an unhandled event returns true in Chrome (the container is a real EventTarget since M4 knife 49)
            true, true, true,
        ]),
        "serviceWorker container must survive X's optional-chained addEventListener"
    );
}

#[tokio::test(flavor = "current_thread")]
async fn test_issue_83_sw_register_resolves_registration() {
    // Pages chain off register(): `register('/sw.js').then(reg => reg.scope)`.
    // The old stub resolved undefined, so the .scope read threw — xhs logs
    // it as "Service Worker registration failed: Cannot read properties of
    // undefined (reading 'scope')" (issue #83). register/ready must resolve
    // a registration-shaped object; getRegistration keeps resolving
    // undefined — nothing ever registered, and a lie there pushes pages
    // into the has-registration branch.
    let mut rt = setup_runtime("<html><body></body></html>");
    rt.set_url("https://www.xiaohongshu.com/explore");
    rt.evaluate(
        // (P7) register follows the script fetch now — stub it ok+JS so
        // this test keeps pinning the RESOLVE face (scope math + shape).
        "globalThis.__fetch = globalThis.fetch;
             globalThis.fetch = function () {
               return Promise.resolve({ ok: true, status: 200,
                 headers: { get: function () { return 'application/javascript'; } } });
             };
             globalThis.__out = {};
             navigator.serviceWorker.register('/sw.js').then(function (reg) {
               __out.scope = reg.scope;
               __out.viaCache = reg.updateViaCache;
               __out.activeNull = reg.active === null;
               __out.methods = typeof reg.update === 'function'
                 && typeof reg.unregister === 'function'
                 && typeof reg.addEventListener === 'function';
               return reg.unregister();
             }).then(function (v) { __out.unreg = v; });
             navigator.serviceWorker.register('sw.js', { scope: '/im/' })
               .then(function (reg) { __out.optScope = reg.scope; });
             navigator.serviceWorker.ready
               .then(function (reg) { __out.readyScope = reg.scope; });
             navigator.serviceWorker.getRegistration()
               .then(function (r) { __out.getReg = (r === undefined); });",
    )
    .unwrap();
    let _ = tokio::time::timeout(std::time::Duration::from_secs(2), rt.run_event_loop()).await;
    let out = rt.evaluate("globalThis.__out").unwrap();
    assert_eq!(
        out,
        serde_json::json!({
            "scope": "https://www.xiaohongshu.com/",
            "viaCache": "imports",
            "activeNull": true,
            "methods": true,
            "unreg": true,
            // register('sw.js', {scope:'/im/'}) on /explore: script
            // resolves against the page dir, scope against the option.
            "optScope": "https://www.xiaohongshu.com/im/",
            "readyScope": "https://www.xiaohongshu.com/",
            "getReg": true,
        }),
        "register/ready resolve registration-shaped objects; getRegistration stays undefined"
    );
}

#[tokio::test(flavor = "current_thread")]
async fn sw_register_reject_faces_p7() {
    // (300015 P7) ark registers a service worker whose script 404s on the
    // CDN; real Chrome REJECTS the register() promise and the app swallows
    // it. Our unconditional resolve was a one-line bot check. Chrome truth
    // (CDP 155, 10-15): !ok -> TypeError "A bad HTTP response code…",
    // non-JS MIME -> SecurityError "unsupported MIME type", cross-origin
    // script -> SecurityError origin mismatch before any fetch. ok+JS
    // keeps resolving the stub registration.
    let mut rt = setup_runtime("<html><body></body></html>");
    rt.set_url("https://ark.xiaohongshu.com/ark");
    rt.evaluate(
            "globalThis.__out = {};
             function stubFetch(status, ct) {
               globalThis.fetch = function () {
                 return Promise.resolve({ ok: status >= 200 && status < 300, status: status,
                   headers: { get: function () { return ct; } } });
               };
             }
             // 404 + application/xml (the live ark SW URL shape)
             stubFetch(404, 'application/xml');
             navigator.serviceWorker.register('/service-worker?hash=1792046827315').then(
               function () { __out.a = 'RESOLVED'; },
               function (e) { __out.a = e.name + '|' + e.message; });
             // 200 + text/html (customer-origin SPA fallback shape)
             stubFetch(200, 'text/html');
             navigator.serviceWorker.register('/sw.js').then(
               function () { __out.b = 'RESOLVED'; },
               function (e) { __out.b = e.name + '|' + e.message; });
             // cross-origin script: rejects before fetch (stub stays armed,
             // proving no fetch happened)
             var fetched = false;
             globalThis.fetch = function () { fetched = true; return Promise.resolve({ ok: true }); };
             navigator.serviceWorker.register('https://other.example/sw.js').then(
               function () { __out.c = 'RESOLVED'; },
               function (e) { __out.c = e.name + '|' + e.message; });
             __out.noFetch = String(!fetched);
             // ok + JS MIME -> resolves with scope
             stubFetch(200, 'application/javascript');
             navigator.serviceWorker.register('/real-sw.js').then(
               function (reg) { __out.d = 'RESOLVED|' + reg.scope; },
               function (e) { __out.d = e.name + '|' + e.message; });",
        )
        .unwrap();
    let _ = tokio::time::timeout(std::time::Duration::from_secs(2), rt.run_event_loop()).await;
    let out = rt.evaluate("globalThis.__out").unwrap();
    let m = out.as_object().unwrap();
    let get = |k: &str| m.get(k).unwrap().as_str().unwrap().to_string();
    assert_eq!(
        get("a"),
        "TypeError|Failed to register a ServiceWorker for scope ('https://ark.xiaohongshu.com/') \
             with script ('https://ark.xiaohongshu.com/service-worker?hash=1792046827315'): \
             A bad HTTP response code (404) was received when fetching the script."
    );
    assert_eq!(
            get("b"),
            "SecurityError|Failed to register a ServiceWorker for scope ('https://ark.xiaohongshu.com/') \
             with script ('https://ark.xiaohongshu.com/sw.js'): \
             The script has an unsupported MIME type ('text/html')."
        );
    assert_eq!(
            get("c"),
            "SecurityError|Failed to register a ServiceWorker: The origin of the provided scriptURL \
             ('https://other.example') does not match the current origin ('https://ark.xiaohongshu.com')."
        );
    assert_eq!(
        get("noFetch"),
        "true",
        "cross-origin rejects before fetching"
    );
    assert_eq!(
        get("d"),
        "RESOLVED|https://ark.xiaohongshu.com/",
        "ok+JS MIME keeps resolving the stub registration"
    );
}

#[test]
fn test_issue_78_jsvmp_env_scan_face() {
    // The XHS jsvmp environment scan reads these four faces directly; all
    // must match Chrome (issue #78): listener registries invisible
    // (WeakMap storage — a Symbol key would still be enumerable),
    // webdriver defined-and-false, sub-ms floats from a 100µs-quantized
    // clock, and interface toStringTags on navigator/window.
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
        .evaluate(
            r#"
            document.addEventListener('x', function () {});
            navigator.connection.addEventListener('change', function () {});
            const xhr = new XMLHttpRequest();
            xhr.addEventListener('load', function () {});
            const fr = new FileReader();
            fr.addEventListener('load', function () {});
            // A ~3ms busy-wait window spans >=30 100µs ticks, so a sub-ms
            // fraction must show up. Sampling a fixed count instead can land
            // every read on one integral tick and flake ~10% of runs.
            const start = performance.now();
            let sawFraction = false, guard = 0;
            while (performance.now() - start < 3 && guard < 2000000) {
                if (performance.now() % 1 !== 0) { sawFraction = true; break; }
                guard++;
            }
            const to = performance.timeOrigin;
            const ns = performance.timing.navigationStart;
            const originSane = to >= ns && to < ns + 1;
            return [
                typeof document._listeners,
                typeof navigator.connection._listeners,
                typeof xhr._listeners,
                typeof fr._listeners,
                typeof navigator.webdriver,
                Object.prototype.toString.call(navigator),
                Object.prototype.toString.call(window),
                sawFraction,
                originSane,
                Number.isInteger(ns),
            ];
        "#,
        )
        .unwrap();
    assert_eq!(
        result,
        serde_json::json!([
            "undefined",
            "undefined",
            "undefined",
            "undefined",
            "boolean",
            "[object Navigator]",
            "[object Window]",
            true,
            true,
            true,
        ])
    );
}

// #114: deno_core's execute_script runs no microtask checkpoint, so under
// the old unconditional-`await` wrapper even a sync-completing expression
// had its done-sentinel parked in a microtask — one that only runs on an
// event-loop turn. On a revived persistent session that first turn gets
// swallowed by multi-second page scripts and the eval burns its whole
// budget into EVAL_TIMEOUT for an expression that had already finished.
// Deterministic repro of the starvation half: poison the microtask queue
// with a self-sustaining promise chain (never empties, so any event-loop
// drain spins until the watchdog), then eval `1+1` under awaitPromise —
// it must settle during execute_script without ever entering the loop.
#[tokio::test(flavor = "current_thread")]
async fn test_await_promise_sync_result_settles_without_event_loop_turn() {
    let mut rt = setup_runtime("<html><body></body></html>");
    rt.evaluate(
            "(function poison(){ var f = function(){ Promise.resolve().then(f); }; Promise.resolve().then(f); })()",
        )
        .unwrap();
    let t0 = std::time::Instant::now();
    let outcome = rt
        .evaluate_remote_outcome("1 + 1", false, true, 5000, None)
        .await
        .unwrap();
    assert_eq!(outcome.info.value.unwrap(), serde_json::json!(2));
    assert!(
            t0.elapsed() < std::time::Duration::from_secs(3),
            "sync result waited {}ms — sentinel must be set during execute_script, not an event-loop turn",
            t0.elapsed().as_millis()
        );
}

#[test]
fn test_url_relative_resolution() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
        .evaluate("new URL('data.json', 'http://example.com/path/page.html').href")
        .unwrap();
    assert_eq!(
        result.as_str().unwrap(),
        "http://example.com/path/data.json"
    );

    let result = rt
        .evaluate("new URL('/api/data', 'http://example.com/path/page.html').href")
        .unwrap();
    assert_eq!(result.as_str().unwrap(), "http://example.com/api/data");

    let result = rt
        .evaluate("new URL('https://other.com/foo', 'http://example.com/bar').href")
        .unwrap();
    assert_eq!(result.as_str().unwrap(), "https://other.com/foo");

    let result = rt
        .evaluate("new URL('sub/file.js', 'http://example.com/a/b/c.html').href")
        .unwrap();
    assert_eq!(
        result.as_str().unwrap(),
        "http://example.com/a/b/sub/file.js"
    );

    let result = rt
        .evaluate("new URL('api.json', 'http://localhost:8080/dir/index.html').href")
        .unwrap();
    assert_eq!(
        result.as_str().unwrap(),
        "http://localhost:8080/dir/api.json"
    );
}

#[test]
fn url_setter_search_hash_port_edges() {
    let mut rt = setup_runtime("<html><body></body></html>");
    // WHATWG setter semantics, verified against Chrome/ada (obscura#1008
    // same face): a bare "?" / "#" sets an EMPTY component that still
    // serializes its delimiter — only the empty string removes it — and
    // the port state parser consumes the leading ASCII digits
    // ("8080abc" → 8080) while rejecting no-digit or >65535 inputs.
    let case = |rt: &mut JsRuntime, expr: &str| -> String {
        rt.evaluate(expr).unwrap().as_str().unwrap().to_string()
    };
    // search: bare "?" keeps the delimiter (with or without a prior query)
    assert_eq!(
        case(
            &mut rt,
            "(() => { const u = new URL('http://x.com/?a'); u.search = '?'; return u.href; })()"
        ),
        "http://x.com/?"
    );
    assert_eq!(
        case(
            &mut rt,
            "(() => { const u = new URL('http://x.com/'); u.search = '?'; return u.href; })()"
        ),
        "http://x.com/?"
    );
    // search: empty string removes the query entirely (no bare "?")
    assert_eq!(
        case(
            &mut rt,
            "(() => { const u = new URL('http://x.com/?a'); u.search = ''; return u.href; })()"
        ),
        "http://x.com/"
    );
    // hash mirrors search
    assert_eq!(
        case(
            &mut rt,
            "(() => { const u = new URL('http://x.com/#f'); u.hash = '#'; return u.href; })()"
        ),
        "http://x.com/#"
    );
    assert_eq!(
        case(
            &mut rt,
            "(() => { const u = new URL('http://x.com/#f'); u.hash = ''; return u.href; })()"
        ),
        "http://x.com/"
    );
    // port: leading digits win, no-digit / overflow inputs are ignored
    assert_eq!(case(&mut rt, "(() => { const u = new URL('http://x.com:9/'); u.port = '8080abc'; return u.href; })()"), "http://x.com:8080/");
    assert_eq!(
        case(
            &mut rt,
            "(() => { const u = new URL('http://x.com:9/'); u.port = '99999'; return u.href; })()"
        ),
        "http://x.com:9/"
    );
    assert_eq!(
        case(
            &mut rt,
            "(() => { const u = new URL('http://x.com:9/'); u.port = 'abc'; return u.href; })()"
        ),
        "http://x.com:9/"
    );
    assert_eq!(
        case(
            &mut rt,
            "(() => { const u = new URL('http://x.com:9/'); u.port = ''; return u.href; })()"
        ),
        "http://x.com/"
    );
}

// importScripts() was a silent no-op stub: Yahoo Finance's worker imports
// protobuf at startup, got `undefined` instead, and the SDK died to a
// TypeError pages could not see (obscura#827 family). The worker source
// executes synchronously inside new Function, so imports cannot be
// fetched at call time — they are preloaded from string-literal targets
// in the source, then replayed from cache via indirect eval, which puts
// top-level `var` in the global lexical scope the Function-wrapped body
// can see (a plain `var` assignment would also work, but declarations
// would not — pin the declaration semantics).
#[tokio::test(flavor = "current_thread")]
async fn worker_import_scripts_expose_declarations_to_worker_body() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
            .evaluate_remote(
                r#"new Promise((resolve, reject) => {
                    const body = "importScripts('data:text/javascript,var%20pbVersion=42');" +
                        "self.onmessage = function(e) { self.postMessage(pbVersion + '|' + typeof window); };";
                    const w = new Worker(URL.createObjectURL(new Blob([body])));
                    w.onerror = e => reject(new Error('worker error: ' + e.message));
                    w.onmessage = e => resolve(e.data);
                    w.postMessage('go');
                })"#,
                true,
                true,
            )
            .await
            .unwrap();
    assert_eq!(result.value.unwrap(), serde_json::json!("42|undefined"));
}

// #98: importScripts replays through the page realm (so declarations
// persist), which exposed the page's MutationObserver to PDD's wheel —
// its bundled scheduler picked the DOM branch and died on
// document.createTextNode. The replay window must mask the
// main-thread-only family like a Chrome worker global, and restore the
// page faces afterwards.
#[tokio::test(flavor = "current_thread")]
async fn worker_import_scripts_see_no_dom_globals() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
            .evaluate_remote(
                r#"new Promise((resolve, reject) => {
                    const imp = "var __domProbe = [typeof MutationObserver, typeof document, typeof window,"
                        + " typeof localStorage, typeof Promise, typeof Math].join('|');";
                    const url = 'data:text/javascript;base64,' + btoa(imp);
                    const body = "importScripts(" + JSON.stringify(url) + ");"
                        + "self.onmessage = function(e) { self.postMessage(__domProbe); };";
                    const w = new Worker(URL.createObjectURL(new Blob([body])));
                    w.onerror = e => reject(new Error('worker error: ' + e.message));
                    w.onmessage = e => resolve([e.data,
                        typeof MutationObserver, typeof document, typeof window].join('#'));
                    w.postMessage('go');
                    setTimeout(() => reject(new Error('no reply')), 2000);
                })"#,
                true,
                true,
            )
            .await
            .unwrap();
    assert_eq!(
        result.value.unwrap(),
        serde_json::json!(
            "undefined|undefined|undefined|undefined|function|object#function#object#object"
        ),
        "imports see Chrome-worker reality; the page global is fully restored after the replay"
    );
}

#[tokio::test(flavor = "current_thread")]
async fn worker_import_scripts_failed_target_fires_error_event() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
        .evaluate_remote(
            r#"new Promise((resolve) => {
                    const body = "importScripts('data:text/javascript;base64,!!!!');" +
                        "self.onmessage = function(e) { self.postMessage('unreached'); };";
                    const w = new Worker(URL.createObjectURL(new Blob([body])));
                    w.onerror = e => resolve('err|' + e.message);
                    w.onmessage = e => resolve('msg|' + e.data);
                    w.postMessage('go');
                })"#,
            true,
            true,
        )
        .await
        .unwrap();
    let msg = result.value.unwrap();
    let msg = msg.as_str().unwrap();
    assert!(
        msg.starts_with("err|"),
        "worker delivered instead of erroring: {msg}"
    );
    assert!(
        msg.contains("failed to load"),
        "error lost the importScripts origin: {msg}"
    );
}

#[test]
fn worker_import_url_extraction_skips_dynamic_arguments() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
            .evaluate(
                r#"return globalThis.__ditingWorkerImportUrls(
                    "importScripts('a.js', \"b.js\"); importScripts(runtimePath); importScripts()")"#,
            )
            .unwrap();
    assert_eq!(result, serde_json::json!(["a.js", "b.js"]));
}

// A bare `onmessage = fn` (no self. prefix) inside the worker body must
// land on the worker scope, not create window.onmessage — the plain
// Function wrapper let the assignment fall through to the page global
// and the worker never received anything (obscura#867 family).
#[tokio::test(flavor = "current_thread")]
async fn worker_bare_onmessage_assignment_receives_messages() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
        .evaluate_remote(
            r#"new Promise((resolve, reject) => {
                    const before = globalThis.onmessage;
                    const body = "onmessage = function(e) { postMessage('bare|' + e.data); };";
                    const w = new Worker(URL.createObjectURL(new Blob([body])));
                    w.onerror = e => reject(new Error('worker error: ' + e.message));
                    w.onmessage = e => resolve([e.data, globalThis.onmessage === before]);
                    w.postMessage('go');
                })"#,
            true,
            true,
        )
        .await
        .unwrap();
    assert_eq!(
        result.value.unwrap(),
        serde_json::json!(["bare|go", true]),
        "bare onmessage works and leaves the page global untouched"
    );
}

// #213: the SharedWorker stub swallowed every port.postMessage and never
// replied. 抖店's sif-dxs security layer builds its request-signing channel
// on exactly this shape (self.onconnect → event.ports[0] → port.start(),
// then every page request waits on it), so the page boot died on the SDK's
// own timeout with a blank screen. Messages posted before the script
// attached its handler must be buffered, not dropped.
#[tokio::test(flavor = "current_thread")]
async fn shared_worker_port_roundtrips_messages() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
            .evaluate_remote(
                r#"new Promise((resolve, reject) => {
                    const body = "self.onconnect = function(e) {"
                        + "  const p = e.ports[0];"
                        + "  p.onmessage = function(ev) { p.postMessage('sw|' + ev.data); };"
                        + "  p.start();"
                        + "};";
                    const w = new SharedWorker(URL.createObjectURL(new Blob([body])), 'probe');
                    const got = [];
                    w.port.onmessage = e => { got.push(e.data); if (got.length === 2) resolve(got); };
                    w.port.postMessage('a');
                    w.port.postMessage('b');
                    setTimeout(() => reject(new Error('no reply: ' + JSON.stringify(got))), 2000);
                })"#,
                true,
                true,
            )
            .await
            .unwrap();
    assert_eq!(result.value.unwrap(), serde_json::json!(["sw|a", "sw|b"]));
}

// Window timer functions are native-shaped ("Illegal invocation" for a
// foreign receiver). A worker script runs under with(self), so its bare
// setTimeout/setInterval calls arrive with the worker scope as receiver —
// that must stay legal. 抖店's sif-dxs worker calls setInterval at boot;
// the receiver check broke it and the page never got past its skeleton.
#[tokio::test(flavor = "current_thread")]
async fn shared_worker_scope_can_call_window_timers() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
            .evaluate_remote(
                r#"new Promise((resolve, reject) => {
                    const body = "var ticks = 0;"
                        + "var iv = setInterval(function() { ticks++; if (ticks === 2) clearInterval(iv); }, 5);"
                        + "setTimeout(function() {}, 1);"
                        + "self.onconnect = function(e) {"
                        + "  const p = e.ports[0];"
                        + "  p.onmessage = function() { setTimeout(function() { p.postMessage('ticks=' + ticks); }, 60); };"
                        + "  p.start();"
                        + "};";
                    const w = new SharedWorker(URL.createObjectURL(new Blob([body])), 'timers');
                    w.port.onmessage = e => resolve(e.data);
                    w.port.postMessage('go');
                    setTimeout(() => reject(new Error('worker timers broke')), 2000);
                })"#,
                true,
                true,
            )
            .await
            .unwrap();
    assert_eq!(result.value.unwrap(), serde_json::json!("ticks=2"));
}

// #98: the with(self) wrapper only shadows names the scope object
// carries — everything else fell through to the page realm, so PDD's
// sharedWorker polyfill saw the page's MutationObserver, picked its DOM
// scheduling branch (document.createTextNode on a text node) and died.
// Chrome workers have no DOM at all: those names must read undefined,
// while genuine worker globals keep resolving.
#[tokio::test(flavor = "current_thread")]
async fn shared_worker_scope_masks_main_thread_globals() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
            .evaluate_remote(
                r#"new Promise((resolve, reject) => {
                    const body = "self.onconnect = function(e) {"
                        + "  const p = e.ports[0];"
                        + "  const probe = [typeof globalThis.MutationObserver, typeof globalThis.document,"
                        + "    typeof globalThis.window].join('|');"
                        + "  p.onmessage = function() {"
                        + "    p.postMessage(probe + '|' + [typeof MutationObserver, typeof document, typeof window,"
                        + "      typeof HTMLElement, typeof localStorage, typeof Promise, typeof Math].join('|'));"
                        + "  };"
                        + "  p.start();"
                        + "};";
                    const w = new SharedWorker(URL.createObjectURL(new Blob([body])), 'mask');
                    w.port.onmessage = e => resolve(e.data);
                    w.port.postMessage('x');
                    setTimeout(() => reject(new Error('no reply')), 2000);
                })"#,
                true,
                true,
            )
            .await
            .unwrap();
    assert_eq!(
            result.value.unwrap(),
            serde_json::json!("undefined|undefined|undefined|undefined|undefined|undefined|undefined|undefined|function|object"),
            "DOM names read undefined in the worker scope — bare names and globalThis reads during the synchronous dispatch — while real globals still fall through"
        );
}

// #98: script/anchor/option .text — Chrome's real IDL attributes. PDD's
// goods-list tracker scan reads el.text on every script without a src;
// external scripts have no children so Chrome answers "" where we
// answered undefined and its .indexOf threw inside the tracker
// inventory.
#[tokio::test(flavor = "current_thread")]
async fn script_anchor_option_text_idl_faces() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
            .evaluate_remote(
                r#"(() => {
                    const s = document.createElement('script');
                    const empty = s.text;
                    s.text = 'var x = 1';
                    const inline = s.text + '/' + s.textContent;
                    const a = document.createElement('a');
                    a.textContent = ' hi ';
                    const o = document.createElement('option');
                    o.textContent = 'opt';
                    return [typeof empty + ':' + JSON.stringify(empty), inline, JSON.stringify(a.text),
                            o.text,
                            Object.getOwnPropertyDescriptor(HTMLScriptElement.prototype, 'text') !== undefined,
                            Object.getOwnPropertyDescriptor(HTMLAnchorElement.prototype, 'text') !== undefined,
                            Object.getOwnPropertyDescriptor(HTMLOptionElement.prototype, 'text') !== undefined,
                            Object.getOwnPropertyDescriptor(HTMLElement.prototype, 'text') === undefined].join('#');
                })()"#,
                false,
                true,
            )
            .await
            .unwrap();
    assert_eq!(
        result.value.unwrap(),
        serde_json::json!("string:\"\"#var x = 1/var x = 1#\" hi \"#opt#true#true#true#true"),
        ".text lives on the three interface prototypes, mirrors textContent, defaults to \"\""
    );
}

// #98: BroadcastChannel delivers as a task to every OTHER open channel
// of the same name, payload structured-cloned per receiver — the old
// postMessage(){} stub hung PDD's titan handshake (replyStatus over
// BroadcastChannel('WebSocketChannel')) and with it mms goods_list.
#[tokio::test(flavor = "current_thread")]
async fn broadcast_channel_delivers_cloned_tasks() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
            .evaluate_remote(
                r#"new Promise((resolve, reject) => {
                    const a1 = new BroadcastChannel('bus');
                    const a2 = new BroadcastChannel('bus');
                    const a3 = new BroadcastChannel('bus');
                    const b1 = new BroadcastChannel('other');
                    const events = [];
                    a2.onmessage = e => { events.push('a2:' + e.data.v + ':' + (e.target === a2)); e.data.v = 'mutated'; };
                    a3.onmessage = e => events.push('a3:' + e.data.v);
                    b1.onmessage = e => events.push('b1:' + e.data.v);
                    a1.onmessage = e => events.push('self:' + e.data.v);
                    a1.postMessage({ v: 'hello' });
                    a1.postMessage({ v: 'second' });
                    setTimeout(() => {
                        a1.close();
                        let threw = '';
                        try { a1.postMessage({ v: 'x' }); } catch (err) { threw = err.name; }
                        a2.close(); a3.close(); b1.close();
                        resolve(events.join('|') + '#' + threw);
                    }, 300);
                    setTimeout(() => reject(new Error('no delivery: ' + JSON.stringify(events))), 2000);
                })"#,
                true,
                true,
            )
            .await
            .unwrap();
    assert_eq!(
            result.value.unwrap(),
            serde_json::json!("a2:hello:true|a3:hello|a2:second:true|a3:second#InvalidStateError"),
            "delivery reaches the same-named channel only, as a task, with per-receiver clones (a2's mutation never reaches a3); postMessage after close throws InvalidStateError"
        );
}

// #98: the PDD topology — a SharedWorker replies through
// BroadcastChannel, not through the port. The page listens on the bus
// and only then posts createSocket on the port.
#[tokio::test(flavor = "current_thread")]
async fn shared_worker_replies_via_broadcast_channel() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
            .evaluate_remote(
                r#"new Promise((resolve, reject) => {
                    const bus = new BroadcastChannel('WebSocketChannel');
                    const body = "self.onconnect = function(e) {"
                        + "  const p = e.ports[0];"
                        + "  const bc = new BroadcastChannel('WebSocketChannel');"
                        + "  p.onmessage = function(ev) {"
                        + "    if (ev.data.type !== 'queryStatus') return;"
                        + "    bc.postMessage({ type: 'replyStatus', data: { uniqueId: ev.data.data.uniqueId } });"
                        + "  };"
                        + "  p.start();"
                        + "};";
                    const w = new SharedWorker(URL.createObjectURL(new Blob([body])), 'bc');
                    w.port.start();
                    bus.onmessage = e => {
                        bus.close();
                        resolve(e.data.type + ':' + e.data.data.uniqueId);
                    };
                    w.port.postMessage({ type: 'queryStatus', data: { uniqueId: 'u1' } });
                    setTimeout(() => reject(new Error('no bus reply')), 2000);
                })"#,
                true,
                true,
            )
            .await
            .unwrap();
    assert_eq!(
            result.value.unwrap(),
            serde_json::json!("replyStatus:u1"),
            "the worker's BroadcastChannel post reaches the page-side listener — same name, cross-context"
        );
}

// Same (url, name) is ONE shared script instance, not one copy per
// construction: its connect counter advances across both clients. The id
// is captured at connect time — reading the shared self.__n at reply time
// would give 2 to both clients whether or not they share a scope, so it
// could not tell sharing from not-sharing.
#[tokio::test(flavor = "current_thread")]
async fn shared_worker_same_key_shares_one_instance() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
        .evaluate_remote(
            r#"new Promise((resolve, reject) => {
                    const body = "self.__n = 0;"
                        + "self.onconnect = function(e) {"
                        + "  const id = ++self.__n;"
                        + "  const p = e.ports[0];"
                        + "  p.onmessage = function() { p.postMessage(id); };"
                        + "};";
                    const u = URL.createObjectURL(new Blob([body]));
                    const a = new SharedWorker(u, 'shared');
                    const b = new SharedWorker(u, 'shared');
                    const seen = [];
                    const done = v => { seen.push(v); if (seen.length === 2) resolve(seen); };
                    a.port.onmessage = e => done(e.data);
                    b.port.onmessage = e => done(e.data);
                    a.port.postMessage('x');
                    b.port.postMessage('x');
                    setTimeout(() => reject(new Error('no reply: ' + JSON.stringify(seen))), 2000);
                })"#,
            true,
            true,
        )
        .await
        .unwrap();
    assert_eq!(
        result.value.unwrap(),
        serde_json::json!([1, 2]),
        "both clients must reach the same scope"
    );
}

// A different name is a different instance, so neither client sees the
// other's connects.
#[tokio::test(flavor = "current_thread")]
async fn shared_worker_distinct_names_are_distinct_instances() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
        .evaluate_remote(
            r#"new Promise((resolve, reject) => {
                    const body = "self.__n = 0;"
                        + "self.onconnect = function(e) {"
                        + "  const id = ++self.__n;"
                        + "  const p = e.ports[0];"
                        + "  p.onmessage = function() { p.postMessage(id); };"
                        + "};";
                    const u = URL.createObjectURL(new Blob([body]));
                    const a = new SharedWorker(u, 'one');
                    const b = new SharedWorker(u, 'two');
                    const seen = [];
                    const done = v => { seen.push(v); if (seen.length === 2) resolve(seen); };
                    a.port.onmessage = e => done(e.data);
                    b.port.onmessage = e => done(e.data);
                    a.port.postMessage('x');
                    b.port.postMessage('x');
                    setTimeout(() => reject(new Error('no reply: ' + JSON.stringify(seen))), 2000);
                })"#,
            true,
            true,
        )
        .await
        .unwrap();
    assert_eq!(result.value.unwrap(), serde_json::json!([1, 1]));
}

// MessagePort was a no-op stub too: a listener registered through
// addEventListener never heard anything. Delivery starts on start() (or on
// the first listener), and messages posted before that are buffered.
#[tokio::test(flavor = "current_thread")]
async fn message_port_buffers_until_start_and_supports_listeners() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
        .evaluate_remote(
            r#"new Promise((resolve) => {
                    const ch = new MessageChannel();
                    const got = [];
                    ch.port2.addEventListener('message', e => got.push(e.data));
                    ch.port1.postMessage('one');
                    ch.port1.postMessage('two');
                    setTimeout(() => resolve([
                        got,
                        ch.port1 instanceof MessagePort,
                        ch.port2 instanceof MessagePort,
                    ]), 50);
                })"#,
            true,
            true,
        )
        .await
        .unwrap();
    assert_eq!(
        result.value.unwrap(),
        serde_json::json!([["one", "two"], true, true])
    );
}

// Anti-fraud SDKs probe the worker's HTTP surface before using it and
// bail with "no supported http request object" when it is bare. fetch is
// on the synthetic scope; XMLHttpRequest resolves through to the shared
// realm's constructor — pin all three readable by bare identifier
// (obscura#851 family).
#[tokio::test(flavor = "current_thread")]
async fn worker_scope_exposes_http_request_surface() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
            .evaluate_remote(
                r#"new Promise((resolve, reject) => {
                    const body = "onmessage = function(e) { postMessage(typeof fetch + '|' + typeof XMLHttpRequest + '|' + typeof Request); };";
                    const w = new Worker(URL.createObjectURL(new Blob([body])));
                    w.onerror = e => reject(new Error('worker error: ' + e.message));
                    w.onmessage = e => resolve(e.data);
                    w.postMessage('go');
                })"#,
                true,
                true,
            )
            .await
            .unwrap();
    assert_eq!(
        result.value.unwrap(),
        serde_json::json!("function|function|function")
    );
}

// A real worker executes its top-level script the moment the source
// lands — collectors that only set up timers/probes and never wait for
// a parent message must still run. The old flow deferred the whole body
// to the first postMessage, so message-less workers never booted
// (obscura#851 family).
#[tokio::test(flavor = "current_thread")]
async fn worker_top_level_runs_without_any_postmessage() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
        .evaluate_remote(
            r#"new Promise((resolve, reject) => {
                    const body = "postMessage('booted');";
                    const w = new Worker(URL.createObjectURL(new Blob([body])));
                    w.onerror = e => reject(new Error('worker error: ' + e.message));
                    w.onmessage = e => resolve(e.data);
                })"#,
            true,
            true,
        )
        .await
        .unwrap();
    assert_eq!(result.value.unwrap(), serde_json::json!("booted"));
}

#[test]
fn document_write_reports_to_mutation_observers() {
    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
        .evaluate(
            r#"
                var scriptTestSetup = true;
                globalThis.__seen = [];
                const observer = new MutationObserver((records) => {
                  for (const record of records) {
                    for (const node of record.addedNodes) globalThis.__seen.push(node.nodeName);
                  }
                });
                observer.observe(document.body, { childList: true });
                document.write('<span id="watched">z</span>');
                observer.takeRecords().forEach((record) => {
                  for (const node of record.addedNodes) globalThis.__seen.push(node.nodeName);
                });
                return globalThis.__seen.join(',');
                "#,
        )
        .unwrap();
    assert_eq!(result, serde_json::json!("SPAN"));
}

/// A Continue resolution that rewrites the request URL must pass the same
/// SSRF gate as the original request and as redirect hops — otherwise a
/// rewrite to an internal address bypasses validate_fetch_url entirely.
#[allow(clippy::await_holding_lock)] // the env guard must span the await — that's the serialization
#[tokio::test(flavor = "current_thread")]
async fn test_intercept_url_rewrite_is_revalidated_against_ssrf() {
    let _env_guard = crate::PRIVATE_NET_ENV_LOCK.lock().unwrap();
    std::env::remove_var("DITING_ALLOW_PRIVATE_NETWORK");

    let mut rt = setup_runtime("<html><body></body></html>");
    let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
    rt.set_intercept_tx(tx);
    rt.set_intercept_enabled(true);

    // Answer every intercepted request with a rewrite to a loopback address.
    tokio::spawn(async move {
        while let Some(req) = rx.recv().await {
            let _ = req
                .resolver
                .send(crate::ops::InterceptResolution::Continue {
                    url: Some("http://127.0.0.1:9/secret".to_string()),
                    method: None,
                    headers: None,
                    body: None,
                });
        }
    });

    let result = rt
        .call_function_on_remote(
            r#"async () => {
                try {
                    await fetch("http://example.com/data.json");
                    return "not-blocked";
                } catch (e) {
                    return "blocked:" + (e && e.message);
                }
            }"#,
            None,
            &[],
            true,
            true,
        )
        .await
        .unwrap();

    let v = result.value.unwrap();
    assert_eq!(v, serde_json::json!("blocked:Failed to fetch"));
}

/// The taobao shop-SPA report (0.3.0): a blocked or CORS-refused fetch
/// left NO row in the network log, so a page whose API calls all died at
/// the SSRF gate read as "never issued a request". The early exit must
/// record a status-0 js_network_event carrying the reason.
#[allow(clippy::await_holding_lock)] // the env guard must span the await — that's the serialization
#[tokio::test(flavor = "current_thread")]
async fn ssrf_blocked_fetch_records_status_zero_event_with_reason() {
    let _env_guard = crate::PRIVATE_NET_ENV_LOCK.lock().unwrap();
    std::env::remove_var("DITING_ALLOW_PRIVATE_NETWORK");

    let mut rt = setup_runtime("<html><body></body></html>");
    let result = rt
        .call_function_on_remote(
            r#"async () => {
                    try {
                        await fetch("http://127.0.0.1:9/secret");
                        return "not-blocked";
                    } catch (e) {
                        return "rejected";
                    }
                }"#,
            None,
            &[],
            true,
            true,
        )
        .await
        .unwrap();
    assert_eq!(result.value.unwrap(), serde_json::json!("rejected"));

    let events = rt.take_js_network_events();
    let blocked = events
        .iter()
        .find(|e| e.url.contains("127.0.0.1:9"))
        .expect("SSRF-blocked fetch must leave a network event");
    assert_eq!(blocked.status, 0);
    let error = blocked.error.as_deref().unwrap_or("");
    assert!(
        error.contains("private/internal IP address"),
        "event must carry the block reason, got: {error}"
    );
    // obscura#1108 absorption: the denial names the opt-in so an
    // operator hitting the deliberate gate learns the flag on the spot.
    assert!(
        error.contains("--allow-private-network") && error.contains("DITING_ALLOW_PRIVATE_NETWORK"),
        "denial must name the opt-in, got: {error}"
    );
}

/// The punished-mtop shape: the response body arrives but carries no
/// Access-Control-Allow-Origin, so the post-response CORS gate refuses it
/// — status 0 to JS, and (before this fix) invisible in /network. The
/// refusal must record a status-0 event with the CORS reason.
#[allow(clippy::await_holding_lock)] // the env guard must span the await — that's the serialization
#[tokio::test(flavor = "current_thread")]
async fn cors_refused_fetch_records_status_zero_event_with_reason() {
    let _env_guard = crate::PRIVATE_NET_ENV_LOCK.lock().unwrap();
    std::env::set_var("DITING_ALLOW_PRIVATE_NETWORK", "1");

    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let port = listener.local_addr().unwrap().port();
    std::thread::spawn(move || {
        use std::io::{Read, Write};
        let (mut stream, _) = listener.accept().unwrap();
        let mut buf = [0u8; 4096];
        let _ = stream.read(&mut buf);
        let body = b"{}";
        let response = format!(
                "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n",
                body.len()
            );
        stream.write_all(response.as_bytes()).unwrap();
        stream.write_all(body).unwrap();
        stream.flush().unwrap();
    });

    let mut rt = setup_runtime("<html><body></body></html>");
    rt.set_url("https://example.com/page");
    let result = rt
        .call_function_on_remote(
            r#"async () => {
                    try {
                        await fetch("http://127.0.0.1:PORT/api");
                        return "not-blocked";
                    } catch (e) {
                        return "rejected:" + (e && e.message);
                    }
                }"#
            .replace("PORT", &port.to_string())
            .as_str(),
            None,
            &[],
            true,
            true,
        )
        .await
        .unwrap();
    let msg = result
        .value
        .unwrap()
        .as_str()
        .unwrap_or_default()
        .to_string();
    assert!(msg.starts_with("rejected:Failed to fetch"), "got: {msg}");

    let events = rt.take_js_network_events();
    let refused = events
        .iter()
        .find(|e| e.url.contains(&format!(":{port}/api")))
        .expect("CORS-refused fetch must leave a network event");
    assert_eq!(refused.status, 0);
    let error = refused.error.as_deref().unwrap_or("");
    assert!(
        error.contains("CORS error"),
        "event must carry the CORS reason, got: {error}"
    );
}

/// #62: transport-layer failures surface to the page exactly as Chrome
/// delivers them — a TypeError whose message is exactly "Failed to fetch".
/// The raw engine reason ("error sending request for uri ...") used to ride
/// the rejection, a string no real browser produces and a face tell on any
/// page that inspects e.message; the detailed reason belongs to the network
/// event, not the promise.
#[allow(clippy::await_holding_lock)] // the env guard must span the await — that's the serialization
#[tokio::test(flavor = "current_thread")]
async fn transport_error_fetch_rejects_with_chrome_typeerror_face() {
    let _env_guard = crate::PRIVATE_NET_ENV_LOCK.lock().unwrap();
    std::env::set_var("DITING_ALLOW_PRIVATE_NETWORK", "1");

    // Bind then drop: a port nothing listens on, so the connection is
    // refused at the transport layer (no CORS leg involved — simple GET).
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let port = listener.local_addr().unwrap().port();
    drop(listener);

    let mut rt = setup_runtime("<html><body></body></html>");
    rt.set_url("https://example.com/page");
    let result = rt
        .call_function_on_remote(
            r#"async () => {
                    try {
                        await fetch("http://127.0.0.1:PORT/api");
                        return "not-blocked";
                    } catch (e) {
                        return [e && e.name, e && e.message, e instanceof TypeError]
                            .map(v => String(v)).join("|");
                    }
                }"#
            .replace("PORT", &port.to_string())
            .as_str(),
            None,
            &[],
            true,
            true,
        )
        .await
        .unwrap();
    let face = result
        .value
        .unwrap()
        .as_str()
        .unwrap_or_default()
        .to_string();
    std::env::remove_var("DITING_ALLOW_PRIVATE_NETWORK");
    assert_eq!(face, "TypeError|Failed to fetch|true", "got: {face}");

    // The observability split Chrome achieves with the console, we keep in
    // the network event: the refusal records status 0 with the real reason.
    let events = rt.take_js_network_events();
    let refused = events
        .iter()
        .find(|e| e.url.contains(&format!(":{port}/api")))
        .expect("refused fetch must leave a network event");
    assert_eq!(refused.status, 0);
}

/// Preflight permission enforcement (obscura "enforce CORS preflight
/// permissions", 04f0475 same-hole): a preflight that allows the origin
/// but never lists Access-Control-Allow-Methods does not consent to a
/// cross-origin PUT — the actual request must not go out. Before the fix
/// the origin-only check passed and the PUT reached the server anyway.
#[allow(clippy::await_holding_lock)] // the env guard must span the await — that's the serialization
#[tokio::test(flavor = "current_thread")]
async fn preflight_without_allow_methods_blocks_the_actual_request() {
    let _env_guard = crate::PRIVATE_NET_ENV_LOCK.lock().unwrap();
    std::env::set_var("DITING_ALLOW_PRIVATE_NETWORK", "1");

    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let port = listener.local_addr().unwrap().port();
    let requests = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
    let seen = requests.clone();
    std::thread::spawn(move || {
        use std::io::{Read, Write};
        // Only the OPTIONS preflight should ever land here; a second
        // connection means the actual PUT leaked through and the test's
        // assertion below fires (recording it either way aids the
        // failure message).
        for _ in 0..2 {
            let Ok((mut stream, _)) = listener.accept() else {
                return;
            };
            let mut buf = [0u8; 8192];
            let _ = stream.read(&mut buf);
            let req = String::from_utf8_lossy(&buf).to_string();
            seen.lock()
                .unwrap()
                .push(req.lines().next().unwrap_or("").to_string());
            let response = "HTTP/1.1 200 OK\r\naccess-control-allow-origin: *\r\ncontent-length: 0\r\nconnection: close\r\n\r\n";
            stream.write_all(response.as_bytes()).unwrap();
            stream.flush().unwrap();
        }
    });

    let mut rt = setup_runtime("<html><body></body></html>");
    rt.set_url("https://example.com/page");
    let result = rt
        .call_function_on_remote(
            r#"async () => {
                    try {
                        const r = await fetch("http://127.0.0.1:PORT/api", {
                            method: "PUT",
                            headers: { "content-type": "application/json" },
                            body: "{}",
                        });
                        return "not-blocked:" + r.status;
                    } catch (e) {
                        return "rejected:" + (e && e.message);
                    }
                }"#
            .replace("PORT", &port.to_string())
            .as_str(),
            None,
            &[],
            true,
            true,
        )
        .await
        .unwrap();
    let msg = result
        .value
        .unwrap()
        .as_str()
        .unwrap_or_default()
        .to_string();
    // #62: Chrome's page face is the bare TypeError; the method refusal
    // reason rides the network event.
    assert_eq!(msg, "rejected:Failed to fetch", "got: {msg}");

    // The actual request never reached the wire: only the OPTIONS hop.
    let served = requests.lock().unwrap().clone();
    assert!(
        served.iter().all(|line| line.starts_with("OPTIONS")),
        "only the preflight may go out, served: {served:?}"
    );

    let events = rt.take_js_network_events();
    let refused = events
        .iter()
        .find(|e| e.url.contains(&format!(":{port}/api")))
        .expect("preflight-refused fetch must leave a network event");
    assert_eq!(refused.status, 0);
    let error = refused.error.as_deref().unwrap_or("");
    assert!(
        error.contains("did not allow method 'PUT'"),
        "event must carry the preflight reason, got: {error}"
    );
}

/// The positive companion: when the preflight DOES list the method and
/// headers, the actual request proceeds and resolves. Guards against the
/// enforcement over-blocking (the safelist value check must not reject
/// what the preflight explicitly allows).
#[allow(clippy::await_holding_lock)] // the env guard must span the await — that's the serialization
#[tokio::test(flavor = "current_thread")]
async fn preflight_that_allows_the_method_lets_the_request_through() {
    let _env_guard = crate::PRIVATE_NET_ENV_LOCK.lock().unwrap();
    std::env::set_var("DITING_ALLOW_PRIVATE_NETWORK", "1");

    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let port = listener.local_addr().unwrap().port();
    std::thread::spawn(move || {
        use std::io::{Read, Write};
        // Hop 1: the OPTIONS preflight with a full consent set.
        let (mut stream, _) = listener.accept().unwrap();
        let mut buf = [0u8; 8192];
        let _ = stream.read(&mut buf);
        let preflight = concat!(
            "HTTP/1.1 204 No Content\r\n",
            "access-control-allow-origin: *\r\n",
            "access-control-allow-methods: PUT, POST\r\n",
            "access-control-allow-headers: content-type\r\n",
            "access-control-max-age: 600\r\n",
            "content-length: 0\r\nconnection: close\r\n\r\n",
        );
        stream.write_all(preflight.as_bytes()).unwrap();
        stream.flush().unwrap();
        // Hop 2: the actual PUT.
        let (mut stream, _) = listener.accept().unwrap();
        let mut buf = [0u8; 8192];
        let _ = stream.read(&mut buf);
        let body = b"ok";
        let response = format!(
                "HTTP/1.1 200 OK\r\naccess-control-allow-origin: *\r\ncontent-length: {}\r\nconnection: close\r\n\r\n",
                body.len()
            );
        stream.write_all(response.as_bytes()).unwrap();
        stream.write_all(body).unwrap();
        stream.flush().unwrap();
    });

    let mut rt = setup_runtime("<html><body></body></html>");
    rt.set_url("https://example.com/page");
    let result = rt
        .call_function_on_remote(
            r#"async () => {
                    try {
                        const r = await fetch("http://127.0.0.1:PORT/api", {
                            method: "PUT",
                            headers: { "content-type": "application/json" },
                            body: "{}",
                        });
                        return "ok:" + r.status + ":" + (await r.text());
                    } catch (e) {
                        return "rejected:" + (e && e.message);
                    }
                }"#
            .replace("PORT", &port.to_string())
            .as_str(),
            None,
            &[],
            true,
            true,
        )
        .await
        .unwrap();
    let msg = result
        .value
        .unwrap()
        .as_str()
        .unwrap_or_default()
        .to_string();
    assert_eq!(
        msg, "ok:200:ok",
        "consented preflight must let the PUT through, got: {msg}"
    );
}

/// Redirect credential retention (obscura#967 same hole): a redirect
/// chain that never leaves the origin keeps the scripted Authorization
/// header on every hop. Guards against over-stripping implementations
/// that drop credentials after ANY redirect.
#[allow(clippy::await_holding_lock)] // the env guard must span the await — that's the serialization
#[tokio::test(flavor = "current_thread")]
async fn same_origin_redirect_keeps_scripted_credentials() {
    let _env_guard = crate::PRIVATE_NET_ENV_LOCK.lock().unwrap();
    std::env::set_var("DITING_ALLOW_PRIVATE_NETWORK", "1");

    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let port = listener.local_addr().unwrap().port();
    let requests = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
    let seen = requests.clone();
    std::thread::spawn(move || {
        use std::io::{Read, Write};
        for _ in 0..3 {
            let Ok((mut stream, _)) = listener.accept() else {
                return;
            };
            let mut buf = [0u8; 8192];
            let _ = stream.read(&mut buf);
            seen.lock()
                .unwrap()
                .push(String::from_utf8_lossy(&buf).to_string());
            let response = match seen.lock().unwrap().len() {
                    1 => concat!(
                        "HTTP/1.1 200 OK\r\n",
                        "access-control-allow-origin: *\r\n",
                        "access-control-allow-methods: GET\r\n",
                        "access-control-allow-headers: authorization\r\n",
                        "content-length: 0\r\nconnection: close\r\n\r\n",
                    )
                    .to_string(),
                    // The 302 itself carries ACAO because a cors-tainted
                    // request CORS-checks every response in the chain.
                    2 => "HTTP/1.1 302 Found\r\naccess-control-allow-origin: *\r\nlocation: /data\r\ncontent-length: 0\r\nconnection: close\r\n\r\n".to_string(),
                    _ => {
                        let body = b"done";
                        format!(
                            "HTTP/1.1 200 OK\r\naccess-control-allow-origin: *\r\ncontent-length: {}\r\nconnection: close\r\n\r\n",
                            body.len()
                        ) + std::str::from_utf8(body).unwrap()
                    }
                };
            stream.write_all(response.as_bytes()).unwrap();
            stream.flush().unwrap();
        }
    });

    let mut rt = setup_runtime("<html><body></body></html>");
    rt.set_url("https://example.com/page");
    let result = rt
        .call_function_on_remote(
            r#"async () => {
                    try {
                        const r = await fetch("http://127.0.0.1:PORT/hop", {
                            headers: { "Authorization": "Bearer token123" },
                        });
                        return "ok:" + r.status + ":" + (await r.text());
                    } catch (e) {
                        return "rejected:" + (e && e.message);
                    }
                }"#
            .replace("PORT", &port.to_string())
            .as_str(),
            None,
            &[],
            true,
            true,
        )
        .await
        .unwrap();
    let msg = result
        .value
        .unwrap()
        .as_str()
        .unwrap_or_default()
        .to_string();
    assert_eq!(
        msg, "ok:200:done",
        "same-origin redirect chain must complete, got: {msg}"
    );

    let hops = requests.lock().unwrap();
    assert_eq!(hops.len(), 3, "expected preflight + /hop + /data");
    let data_hop = hops[2].to_ascii_lowercase();
    assert!(
        data_hop.starts_with("get /data"),
        "third hop must be the redirected GET, got: {}",
        hops[2].lines().next().unwrap_or("")
    );
    assert!(
        data_hop.contains("authorization: bearer token123"),
        "same-origin redirect must keep the Authorization header, got: {data_hop}"
    );
}

/// Redirect credential stripping (obscura#967 same hole): once the chain
/// crosses origins the scripted Authorization header must stop riding —
/// it went out on the first hop (that origin was told at fetch time) but
/// must never reach the second, different origin.
#[allow(clippy::await_holding_lock)] // the env guard must span the await — that's the serialization
#[tokio::test(flavor = "current_thread")]
async fn cross_origin_redirect_strips_scripted_credentials() {
    let _env_guard = crate::PRIVATE_NET_ENV_LOCK.lock().unwrap();
    std::env::set_var("DITING_ALLOW_PRIVATE_NETWORK", "1");

    let listener_a = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let port_a = listener_a.local_addr().unwrap().port();
    let requests_a = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
    let seen_a = requests_a.clone();
    let listener_b = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let port_b = listener_b.local_addr().unwrap().port();
    let requests_b = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
    let seen_b = requests_b.clone();

    std::thread::spawn(move || {
        use std::io::{Read, Write};
        for _ in 0..2 {
            let Ok((mut stream, _)) = listener_a.accept() else {
                return;
            };
            let mut buf = [0u8; 8192];
            let _ = stream.read(&mut buf);
            seen_a
                .lock()
                .unwrap()
                .push(String::from_utf8_lossy(&buf).to_string());
            let response = match seen_a.lock().unwrap().len() {
                    1 => concat!(
                        "HTTP/1.1 200 OK\r\n",
                        "access-control-allow-origin: *\r\n",
                        "access-control-allow-methods: GET\r\n",
                        "access-control-allow-headers: authorization\r\n",
                        "content-length: 0\r\nconnection: close\r\n\r\n",
                    )
                    .to_string(),
                    _ => format!(
                        "HTTP/1.1 302 Found\r\naccess-control-allow-origin: *\r\nlocation: http://127.0.0.1:{}/data\r\ncontent-length: 0\r\nconnection: close\r\n\r\n",
                        port_b
                    ),
                };
            stream.write_all(response.as_bytes()).unwrap();
            stream.flush().unwrap();
        }
    });
    std::thread::spawn(move || {
        use std::io::{Read, Write};
        let Ok((mut stream, _)) = listener_b.accept() else {
            return;
        };
        let mut buf = [0u8; 8192];
        let _ = stream.read(&mut buf);
        seen_b
            .lock()
            .unwrap()
            .push(String::from_utf8_lossy(&buf).to_string());
        let body = b"secret";
        let response = format!(
                "HTTP/1.1 200 OK\r\naccess-control-allow-origin: *\r\ncontent-length: {}\r\nconnection: close\r\n\r\n",
                body.len()
            );
        stream.write_all(response.as_bytes()).unwrap();
        stream.write_all(body).unwrap();
        stream.flush().unwrap();
    });

    let mut rt = setup_runtime("<html><body></body></html>");
    rt.set_url("https://example.com/page");
    let result = rt
        .call_function_on_remote(
            r#"async () => {
                    try {
                        const r = await fetch("http://127.0.0.1:PORTA/hop", {
                            headers: { "Authorization": "Bearer secret-token" },
                        });
                        return "ok:" + r.status + ":" + (await r.text());
                    } catch (e) {
                        return "rejected:" + (e && e.message);
                    }
                }"#
            .replace("PORTA", &port_a.to_string())
            .as_str(),
            None,
            &[],
            true,
            true,
        )
        .await
        .unwrap();
    let msg = result
        .value
        .unwrap()
        .as_str()
        .unwrap_or_default()
        .to_string();
    assert_eq!(
        msg, "ok:200:secret",
        "redirect chain must complete, got: {msg}"
    );

    let hops_a = requests_a.lock().unwrap();
    assert_eq!(
        hops_a.len(),
        2,
        "origin A sees the preflight and the first GET"
    );
    let first_hop = hops_a[1].to_ascii_lowercase();
    assert!(
        first_hop.contains("authorization: bearer secret-token"),
        "the initial cross-origin request carries the header it was given, got: {first_hop}"
    );

    let hops_b = requests_b.lock().unwrap();
    assert_eq!(hops_b.len(), 1, "origin B sees exactly the redirected GET");
    let second_hop = hops_b[0].to_ascii_lowercase();
    assert!(
        second_hop.starts_with("get /data"),
        "hop 2 must be the redirected GET, got: {}",
        hops_b[0].lines().next().unwrap_or("")
    );
    assert!(
        !second_hop.contains("authorization"),
        "cross-origin redirect must strip the Authorization header, got: {second_hop}"
    );
}

/// Redirect CORS enforcement (obscura#973 same hole): with a cors-tainted
/// request, the 302 response itself must pass the CORS check before the
/// follow happens — a redirect response without
/// Access-Control-Allow-Origin blocks the fetch (status 0 to JS) and the
/// second hop never goes out.
#[allow(clippy::await_holding_lock)] // the env guard must span the await — that's the serialization
#[tokio::test(flavor = "current_thread")]
async fn cross_origin_redirect_without_acao_is_blocked() {
    let _env_guard = crate::PRIVATE_NET_ENV_LOCK.lock().unwrap();
    std::env::set_var("DITING_ALLOW_PRIVATE_NETWORK", "1");

    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let port = listener.local_addr().unwrap().port();
    std::thread::spawn(move || {
        use std::io::{Read, Write};
        // Exactly one connection: a second one would mean the redirected
        // GET leaked past the redirect-response CORS check.
        let Ok((mut stream, _)) = listener.accept() else {
            return;
        };
        let mut buf = [0u8; 8192];
        let _ = stream.read(&mut buf);
        let response = format!(
                "HTTP/1.1 302 Found\r\nlocation: http://127.0.0.1:{}/data\r\ncontent-length: 0\r\nconnection: close\r\n\r\n",
                port
            );
        stream.write_all(response.as_bytes()).unwrap();
        stream.flush().unwrap();
    });

    let mut rt = setup_runtime("<html><body></body></html>");
    rt.set_url("https://example.com/page");
    let result = rt
        .call_function_on_remote(
            r#"async () => {
                    try {
                        await fetch("http://127.0.0.1:PORT/hop");
                        return "not-blocked";
                    } catch (e) {
                        return "rejected:" + (e && e.message);
                    }
                }"#
            .replace("PORT", &port.to_string())
            .as_str(),
            None,
            &[],
            true,
            true,
        )
        .await
        .unwrap();
    let msg = result
        .value
        .unwrap()
        .as_str()
        .unwrap_or_default()
        .to_string();
    assert!(msg.starts_with("rejected:Failed to fetch"), "got: {msg}");

    let events = rt.take_js_network_events();
    let blocked = events
        .iter()
        .find(|e| e.error.as_deref().unwrap_or("").contains("redirect"))
        .expect("blocked redirect must leave a network event");
    assert_eq!(blocked.status, 0);
    let error = blocked.error.as_deref().unwrap_or("");
    assert!(
        error.contains("CORS error"),
        "event must carry the redirect-CORS reason, got: {error}"
    );
}

/// Redirect downgrade (obscura#973 family, body half): a POST that lands
/// on a 302 re-issues as GET with the body headers gone — content-type
/// describes a body that no longer exists.
#[allow(clippy::await_holding_lock)] // the env guard must span the await — that's the serialization
#[tokio::test(flavor = "current_thread")]
async fn redirect_downgrade_drops_body_headers() {
    let _env_guard = crate::PRIVATE_NET_ENV_LOCK.lock().unwrap();
    std::env::set_var("DITING_ALLOW_PRIVATE_NETWORK", "1");

    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let port = listener.local_addr().unwrap().port();
    let requests = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
    let seen = requests.clone();
    std::thread::spawn(move || {
        use std::io::{Read, Write};
        for _ in 0..3 {
            let Ok((mut stream, _)) = listener.accept() else {
                return;
            };
            let mut buf = [0u8; 8192];
            let _ = stream.read(&mut buf);
            seen.lock()
                .unwrap()
                .push(String::from_utf8_lossy(&buf).to_string());
            let response = match seen.lock().unwrap().len() {
                    1 => concat!(
                        "HTTP/1.1 200 OK\r\n",
                        "access-control-allow-origin: *\r\n",
                        "access-control-allow-methods: POST\r\n",
                        "access-control-allow-headers: content-type\r\n",
                        "content-length: 0\r\nconnection: close\r\n\r\n",
                    )
                    .to_string(),
                    2 => "HTTP/1.1 302 Found\r\naccess-control-allow-origin: *\r\nlocation: /data\r\ncontent-length: 0\r\nconnection: close\r\n\r\n".to_string(),
                    _ => {
                        let body = b"moved";
                        format!(
                            "HTTP/1.1 200 OK\r\naccess-control-allow-origin: *\r\ncontent-length: {}\r\nconnection: close\r\n\r\n",
                            body.len()
                        ) + std::str::from_utf8(body).unwrap()
                    }
                };
            stream.write_all(response.as_bytes()).unwrap();
            stream.flush().unwrap();
        }
    });

    let mut rt = setup_runtime("<html><body></body></html>");
    rt.set_url("https://example.com/page");
    let result = rt
        .call_function_on_remote(
            r#"async () => {
                    try {
                        const r = await fetch("http://127.0.0.1:PORT/hop", {
                            method: "POST",
                            headers: { "content-type": "application/json" },
                            body: "{\"a\":1}",
                        });
                        return "ok:" + r.status + ":" + (await r.text());
                    } catch (e) {
                        return "rejected:" + (e && e.message);
                    }
                }"#
            .replace("PORT", &port.to_string())
            .as_str(),
            None,
            &[],
            true,
            true,
        )
        .await
        .unwrap();
    let msg = result
        .value
        .unwrap()
        .as_str()
        .unwrap_or_default()
        .to_string();
    assert_eq!(
        msg, "ok:200:moved",
        "redirected POST must complete as GET, got: {msg}"
    );

    let hops = requests.lock().unwrap();
    assert_eq!(hops.len(), 3, "expected preflight + POST + redirected GET");
    assert!(
        hops[1].starts_with("POST /hop"),
        "hop 1 must be the POST, got: {}",
        hops[1].lines().next().unwrap_or("")
    );
    let downgraded = hops[2].to_ascii_lowercase();
    assert!(
        downgraded.starts_with("get /data"),
        "302 must downgrade POST to GET, got: {}",
        hops[2].lines().next().unwrap_or("")
    );
    assert!(
        !downgraded.contains("content-type"),
        "the downgraded GET must drop the body's content-type, got: {downgraded}"
    );
}

/// navigator.sendBeacon used to be a stub that returned true without
/// sending anything — pd-lib's three detection beacons silently vanished
/// (proxydetect.live never settled). A beacon must leave the machine as a
/// fire-and-forget POST; the relative URL resolves against the document.
#[allow(clippy::await_holding_lock)] // the env guard must span the await — that's the serialization
#[tokio::test(flavor = "current_thread")]
async fn send_beacon_relative_url_posts_with_text_plain() {
    let _env_guard = crate::PRIVATE_NET_ENV_LOCK.lock().unwrap();
    std::env::set_var("DITING_ALLOW_PRIVATE_NETWORK", "1");

    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let port = listener.local_addr().unwrap().port();
    let requests = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
    let seen = requests.clone();
    std::thread::spawn(move || {
        use std::io::{Read, Write};
        let Ok((mut stream, _)) = listener.accept() else {
            return;
        };
        let mut buf = [0u8; 8192];
        let _ = stream.read(&mut buf);
        seen.lock()
            .unwrap()
            .push(String::from_utf8_lossy(&buf).to_string());
        let response = "HTTP/1.1 204 No Content\r\ncontent-length: 0\r\nconnection: close\r\n\r\n";
        let _ = stream.write_all(response.as_bytes());
        let _ = stream.flush();
    });

    let mut rt = setup_runtime("<html><body></body></html>");
    rt.set_url(&format!("http://127.0.0.1:{port}/page"));
    let result = rt
        .call_function_on_remote(
            r#"async () => {
                    const ok = navigator.sendBeacon("/beacon", "hello");
                    await new Promise(r => setTimeout(r, 800));
                    return "queued:" + ok;
                }"#,
            None,
            &[],
            true,
            true,
        )
        .await
        .unwrap();
    let msg = result
        .value
        .unwrap()
        .as_str()
        .unwrap_or_default()
        .to_string();
    assert_eq!(
        msg, "queued:true",
        "sendBeacon must report a queued transfer"
    );

    let hops = requests.lock().unwrap();
    assert_eq!(hops.len(), 1, "exactly one beacon must reach the wire");
    let raw = hops[0].to_ascii_lowercase();
    assert!(
        raw.starts_with("post /beacon"),
        "beacon must POST to the resolved relative URL, got: {}",
        hops[0].lines().next().unwrap_or("")
    );
    assert!(
        raw.contains(
            "content-type: text/plain;charset=UTF-8"
                .to_ascii_lowercase()
                .as_str()
        ),
        "string data must ride text/plain;charset=UTF-8, got: {raw}"
    );
    assert!(
        raw.contains("\r\n\r\nhello"),
        "string data must be the body, got: {raw}"
    );
}

