    assert_eq!(o["coerce"], serde_json::json!([2, 3, "null", "undefined"]));
    assert_eq!(o["sub"], serde_json::json!([true, "q"]));
    assert_eq!(o["events"], 2);
    assert_eq!(o["hls_probe"], "inf ok");
